 data.Lock()
 defer data.Unlock()
 var err error
 data.fallback,err=os.ReadFile(fallbackImage); if err!=nil{return err}
 defaultHash:=fmt.Sprintf("%x",sha256.Sum256(data.fallback))
 data.users=make(map[int64]User)
 data.names=make(map[string]int64)
 data.images=make(map[int64][]byte)
 data.streams=make(map[int64]Livestream)
 data.tags=make(map[int64]Tag)
 var users []UserModel
 if err=dbConn.Select(&users,"SELECT * FROM users");err!=nil{return err}
 for _,u:=range users {data.users[u.ID]=User{ID:u.ID,Name:u.Name,DisplayName:u.DisplayName,Description:u.Description,IconHash:defaultHash};data.names[u.Name]=u.ID}
 var themes []ThemeModel
 if err=dbConn.Select(&themes,"SELECT * FROM themes");err!=nil{return err}
 for _,t:=range themes {u:=data.users[t.UserID];u.Theme=Theme{t.ID,t.DarkMode};data.users[t.UserID]=u}
 rows,err:=dbConn.Query("SELECT user_id,image FROM icons");if err!=nil{return err}
 defer rows.Close()
 for rows.Next(){var id int64;var img []byte;if err=rows.Scan(&id,&img);err!=nil{return err};data.setImage(id,img)}
