package main

import (
 "fmt"
 "log"
 "net"
 "os"
 "strings"
 "sync"
 "time"

 "github.com/jmoiron/sqlx"
 "golang.org/x/net/dns/dnsmessage"
)

// PowerDNS retains the complete authoritative zone. The UDP front end serves
// address and negative answers from its copy, forwarding other query types.
var zone struct{
 sync.RWMutex
 records map[string][4]byte
 db *sqlx.DB
}
func loadZone() error {
 if zone.db==nil{return nil}
 var rows []struct{Name string;Content string}
 if err:=zone.db.Select(&rows,"SELECT name,content FROM records WHERE type='A' AND disabled=0");err!=nil{return err}
 records:=make(map[string][4]byte,len(rows))
 for _,r:=range rows{if ip:=net.ParseIP(r.Content).To4();ip!=nil{records[strings.ToLower(r.Name)+"."]=[4]byte(ip)}}
 zone.Lock();zone.records=records;zone.Unlock();return nil
}
func addAddress(name string)error{
 fqdn:=strings.ToLower(name)+".u.isucon.dev"
 _,err:=zone.db.Exec("INSERT INTO records(domain_id,name,type,content,ttl,prio,disabled,auth) SELECT id,?,'A',?,60,0,0,1 FROM domains WHERE name='u.isucon.dev'",fqdn,powerDNSSubdomainAddress)
 if err!=nil{return err}
 zone.Lock();zone.records[fqdn+"."]=[4]byte(net.ParseIP(powerDNSSubdomainAddress).To4());zone.Unlock();return nil
}
func runDNS() error {
 db,err:=sqlx.Connect("mysql",os.Getenv("ISUPIPE_ZONE_DSN"));if err!=nil{return err}
 zone.db=db;if err=loadZone();err!=nil{return err}
 sock,err:=net.ListenUDP("udp",&net.UDPAddr{Port:53});if err!=nil{return err}
 for i:=0;i<2;i++{go func(){
 buf:=make([]byte,4096)
 for{n,addr,err:=sock.ReadFromUDPAddrPort(buf);if err!=nil{log.Print(err);return}
 var p dnsmessage.Parser;h,err:=p.Start(buf[:n]);if err!=nil||h.Response{continue}
 q,err:=p.Question();if err!=nil{continue}
 name:=strings.ToLower(q.Name.String())
 if q.Type!=dnsmessage.TypeA || q.Class!=dnsmessage.ClassINET || (name!="u.isucon.dev." && !strings.HasSuffix(name,".u.isucon.dev.")){
 resp,err:=dnsBackend(buf[:n]);if err==nil{sock.WriteToUDPAddrPort(resp,addr)};continue
 }
 zone.RLock();ip,found:=zone.records[name];zone.RUnlock()
 response:=dnsmessage.Header{ID:h.ID,Response:true,Authoritative:true,RecursionDesired:h.RecursionDesired}
 if !found{response.RCode=dnsmessage.RCodeNameError}
 b:=dnsmessage.NewBuilder(nil,response);b.EnableCompression()
 if b.StartQuestions()!=nil||b.Question(q)!=nil{continue}
 if found {if b.StartAnswers()!=nil||b.AResource(dnsmessage.ResourceHeader{Name:q.Name,Class:q.Class,TTL:60},dnsmessage.AResource{A:ip})!=nil{continue}
 }else{
 if b.StartAuthorities()!=nil{continue}
 domain:=dnsmessage.MustNewName("u.isucon.dev.")
 if b.SOAResource(dnsmessage.ResourceHeader{Name:domain,Class:q.Class,TTL:0},dnsmessage.SOAResource{NS:dnsmessage.MustNewName("ns1.u.isucon.dev."),MBox:dnsmessage.MustNewName("hostmaster.u.isucon.dev."),Refresh:10800,Retry:3600,Expire:604800})!=nil{continue}
 }
 packet,err:=b.Finish();if err==nil{sock.WriteToUDPAddrPort(packet,addr)}
 }
 }()}
 return nil
}
func dnsBackend(query []byte)([]byte,error){
 conn,err:=net.DialTimeout("udp","127.0.0.1:5353",time.Second);if err!=nil{return nil,err};defer conn.Close()
 conn.SetDeadline(time.Now().Add(time.Second));if _,err=conn.Write(query);err!=nil{return nil,err}
 buf:=make([]byte,4096);n,err:=conn.Read(buf);if err!=nil{return nil,fmt.Errorf("DNS backend: %w",err)};return buf[:n],nil
}
EOF
