 viewers map[int64]int64
 viewersCount int64
 tip int64
 maxTip int64
 emoji map[string]int64
}
type wordPattern struct{ literal string; pattern *regexp.Regexp }
func patternFor(word string)wordPattern{
 if !strings.ContainsAny(word,"%_\\\\"){return wordPattern{literal:word}}
 var b strings.Builder
 b.WriteString("(?s)")
 escaped:=false
 for _,r:=range word{
 if escaped{b.WriteString(regexp.QuoteMeta(string(r)));escaped=false;continue}
 switch r{case '\\\\':escaped=true;case '%':b.WriteString(".*");case '_':b.WriteByte('.');default:b.WriteString(regexp.QuoteMeta(string(r)))}
 }
 if escaped{b.WriteString(\`\\\\\`)}
 return wordPattern{pattern:regexp.MustCompile(b.String())}
}
func(w wordPattern)matches(comment string)bool{if w.pattern!=nil{return w.pattern.MatchString(comment)};return strings.Contains(comment,w.literal)}
