}
func(a *activityState)addComment(m LivecommentModel){
 s:=a.stream(m.LivestreamID);s.comments=append(s.comments,m);s.tip+=m.Tip;a.totalTip+=m.Tip;if m.Tip>s.maxTip{s.maxTip=m.Tip};a.comments[m.ID]=m
}
func(a *activityState)addReaction(m ReactionModel){
 s:=a.stream(m.LivestreamID);s.reactions=append(s.reactions,m);s.emoji[m.EmojiName]++
}
func loadActivity()error{
 activity.Lock();defer activity.Unlock()
 activity.streams=make(map[int64]*streamActivity);activity.comments=make(map[int64]LivecommentModel);activity.totalTip=0
 var comments []struct{LivecommentModel;Hidden bool}
 if err:=dbConn.Select(&comments,"SELECT * FROM livecomments ORDER BY created_at,id");err!=nil{return err}
 for _,m:=range comments{if m.Hidden{activity.comments[m.ID]=m.LivecommentModel}else{activity.addComment(m.LivecommentModel)}}
 var reactions []ReactionModel
 if err:=dbConn.Select(&reactions,"SELECT * FROM reactions ORDER BY created_at,id");err!=nil{return err}
 for _,m:=range reactions{activity.addReaction(m)}
 var reports []LivecommentReportModel
 if err:=dbConn.Select(&reports,"SELECT * FROM livecomment_reports ORDER BY id");err!=nil{return err}
 for _,m:=range reports{s:=activity.stream(m.LivestreamID);s.reports=append(s.reports,m)}
 var words []NGWord
 if err:=dbConn.Select(&words,"SELECT * FROM ng_words ORDER BY created_at,id");err!=nil{return err}
 for _,m:=range words{s:=activity.stream(m.LivestreamID);s.words=append(s.words,m);s.patterns=append(s.patterns,patternFor(m.Word))}
 var viewers []LivestreamViewerModel
 if err:=dbConn.Select(&viewers,"SELECT user_id,livestream_id,created_at FROM livestream_viewers_history");err!=nil{return err}
 for _,v:=range viewers{s:=activity.stream(v.LivestreamID);s.viewers[v.UserID]++;s.viewersCount++}
