 streamID,err=strconv.ParseInt(c.Param("livestream_id"),10,64);if err!=nil{err=echo.NewHTTPError(400,"invalid livestream id");return}
 sess,_:=session.Get(defaultSessionIDKey,c);userID=sess.Values[defaultUserIDKey].(int64);return
