 if _,err:=lookupStream(id);err!=nil{return echo.NewHTTPError(404,"livestream not found")}
 mu:=&writers[uint64(id)%256];mu.Lock();defer mu.Unlock()
 activity.RLock();s:=activity.streams[id];spam:=false;if s!=nil{for _,w:=range s.patterns{if w.matches(req.Comment){spam=true;break}}};activity.RUnlock()
 if spam{return echo.NewHTTPError(400,"このコメントがスパム判定されました")}
 m:=LivecommentModel{UserID:uid,LivestreamID:id,Comment:req.Comment,Tip:req.Tip,CreatedAt:time.Now().Unix()}
 res,err:=dbConn.ExecContext(c.Request().Context(),"INSERT INTO livecomments(user_id,livestream_id,comment,tip,created_at) VALUES(?,?,?,?,?)",uid,id,m.Comment,m.Tip,m.CreatedAt);if err!=nil{return err}
 if m.ID,err=res.LastInsertId();err!=nil{return err}
 activity.Lock();activity.addComment(m);activity.Unlock()
 return c.JSON(201,commentView(m))
}
