 id,uid,err:=streamRequest(c);if err!=nil{return err}
 var req PostReactionRequest;if err=parseBody(c,&req);err!=nil{return err}
 if _,err:=lookupStream(id);err!=nil{return echo.NewHTTPError(404,"livestream not found")}
 mu:=&writers[uint64(id)%256];mu.Lock();defer mu.Unlock()
 m:=ReactionModel{UserID:uid,LivestreamID:id,EmojiName:req.EmojiName,CreatedAt:time.Now().Unix()}
 res,err:=dbConn.ExecContext(c.Request().Context(),"INSERT INTO reactions(user_id,livestream_id,emoji_name,created_at) VALUES(?,?,?,?)",uid,id,m.EmojiName,m.CreatedAt);if err!=nil{return err}
 if m.ID,err=res.LastInsertId();err!=nil{return err}
 activity.Lock();activity.addReaction(m);activity.Unlock()
 return c.JSON(201,reactionView(m))
}
func timeline(c echo.Context,reactions bool)error{
 id,_,err:=streamRequest(c);if err!=nil{return err};limit:=int(^uint(0)>>1)
 if raw:=c.QueryParam("limit");raw!=""{limit,err=strconv.Atoi(raw);if err!=nil||limit<0{return echo.NewHTTPError(400,"invalid limit")}}
 activity.RLock();s:=activity.streams[id]
 if reactions{var models []ReactionModel;if s!=nil{models=s.reactions};if len(models)>limit{models=models[len(models)-limit:]};models=append([]ReactionModel(nil),models...);activity.RUnlock()
 rows:=make([]Reaction,len(models));for i,m:=range models{rows[len(rows)-1-i]=reactionView(m)};return c.JSON(200,rows)}
 var models []LivecommentModel;if s!=nil{models=s.comments};if len(models)>limit{models=models[len(models)-limit:]};models=append([]LivecommentModel(nil),models...);activity.RUnlock()
 rows:=make([]Livecomment,len(models));for i,m:=range models{rows[len(rows)-1-i]=commentView(m)};return c.JSON(200,rows)
}
func moderate(c echo.Context)error{
 id,uid,err:=streamRequest(c);if err!=nil{return err}
 stream,err:=lookupStream(id);if err!=nil||stream.Owner.ID!=uid{return echo.NewHTTPError(400,"not stream owner")}
 var req ModerateRequest;if err=parseBody(c,&req);err!=nil{return err}
 mu:=&writers[uint64(id)%256];mu.Lock();defer mu.Unlock()
 ctx:=c.Request().Context();tx,err:=dbConn.BeginTxx(ctx,nil);if err!=nil{return err};defer tx.Rollback()
 m:=NGWord{UserID:uid,LivestreamID:id,Word:req.NGWord,CreatedAt:time.Now().Unix()}
 res,err:=tx.ExecContext(ctx,"INSERT INTO ng_words(user_id,livestream_id,word,created_at) VALUES(?,?,?,?)",uid,id,m.Word,m.CreatedAt);if err!=nil{return err};m.ID,err=res.LastInsertId();if err!=nil{return err}
 pattern:=patternFor(m.Word)
 activity.RLock();var hidden []int64;if s:=activity.streams[id];s!=nil{for _,v:=range s.comments{if pattern.matches(v.Comment){hidden=append(hidden,v.ID)}}};activity.RUnlock()
 if len(hidden)>0{query,args,err:=sqlx.In("UPDATE livecomments SET hidden=1 WHERE id IN (?)",hidden);if err!=nil{return err};if _,err=tx.ExecContext(ctx,query,args...);err!=nil{return err}}
 if err=tx.Commit();err!=nil{return err}
 activity.Lock();s:=activity.stream(id);s.words=append(s.words,m);s.patterns=append(s.patterns,pattern)
 kept:=s.comments[:0];s.maxTip=0
 for _,v:=range s.comments{if pattern.matches(v.Comment){activity.totalTip-=v.Tip;s.tip-=v.Tip}else{kept=append(kept,v);if v.Tip>s.maxTip{s.maxTip=v.Tip}}};s.comments=kept;activity.Unlock()
 return c.JSON(201,map[string]int64{"word_id":m.ID})
}
