command:
cat >> go/activity.go <<'EOF'
func postReport(c echo.Context)error{
 id,uid,err:=streamRequest(c);if err!=nil{return err}
 cid,err:=strconv.ParseInt(c.Param("livecomment_id"),10,64);if err!=nil{return echo.NewHTTPError(400,"invalid comment id")}
 mu:=&writers[uint64(id)%256];mu.Lock();defer mu.Unlock()
 activity.RLock();comment,ok:=activity.comments[cid];activity.RUnlock();if !ok||comment.LivestreamID!=id{return echo.NewHTTPError(404,"comment not found")}
 m:=LivecommentReportModel{UserID:uid,LivestreamID:id,LivecommentID:cid,CreatedAt:time.Now().Unix()}
 res,err:=dbConn.ExecContext(c.Request().Context(),"INSERT INTO livecomment_reports(user_id,livestream_id,livecomment_id,created_at) VALUES(?,?,?,?)",uid,id,cid,m.CreatedAt);if err!=nil{return err};m.ID,err=res.LastInsertId();if err!=nil{return err}
 activity.Lock();s:=activity.stream(id);s.reports=append(s.reports,m);activity.Unlock()
 u,_:=lookupUser(uid);return c.JSON(201,LivecommentReport{ID:m.ID,Reporter:u,Livecomment:commentView(comment),CreatedAt:m.CreatedAt})
}
func listReports(c echo.Context)error{
 id,uid,err:=streamRequest(c);if err!=nil{return err};stream,err:=lookupStream(id);if err!=nil{return echo.NewHTTPError(404,"stream not found")};if stream.Owner.ID!=uid{return echo.NewHTTPError(403,"not stream owner")}
 activity.RLock();out:=[]LivecommentReport{};if s:=activity.streams[id];s!=nil{out=make([]LivecommentReport,0,len(s.reports));for _,r:=range s.reports{u,_:=lookupUser(r.UserID);out=append(out,LivecommentReport{ID:r.ID,Reporter:u,Livecomment:commentView(activity.comments[r.LivecommentID]),CreatedAt:r.CreatedAt})}};activity.RUnlock();return c.JSON(200,out)
}
func listWords(c echo.Context)error{
 id,uid,err:=streamRequest(c);if err!=nil{return err}
 activity.RLock();out:=[]NGWord{};if s:=activity.streams[id];s!=nil{for i:=len(s.words)-1;i>=0;i--{if s.words[i].UserID==uid{out=append(out,s.words[i])}}};activity.RUnlock();return c.JSON(200,out)
}
func visit(c echo.Context,enter bool)error{
 id,uid,err:=streamRequest(c);if err!=nil{return err}
 mu:=&writers[uint64(id)%256];mu.Lock();defer mu.Unlock()
 if enter{_,err=dbConn.ExecContext(c.Request().Context(),"INSERT INTO livestream_viewers_history(user_id,livestream_id,created_at) VALUES(?,?,?)",uid,id,time.Now().Unix())}else{_,err=dbConn.ExecContext(c.Request().Context(),"DELETE FROM livestream_viewers_history WHERE user_id=? AND livestream_id=?",uid,id)}
 if err!=nil{return err}
 activity.Lock();s:=activity.stream(id);if enter{s.viewers[uid]++;s.viewersCount++}else{s.viewersCount-=s.viewers[uid];delete(s.viewers,uid)};activity.Unlock();return c.NoContent(200)
}
func streamStats(c echo.Context)error{
 id,_,err:=streamRequest(c);if err!=nil{return err};if _,err=lookupStream(id);err!=nil{return echo.NewHTTPError(400,"stream not found")}
 activity.RLock();data.RLock()
 result:=LivestreamStatistics{Rank:1};var score int64
 if s:=activity.streams[id];s!=nil{result.ViewersCount=s.viewersCount;result.TotalReactions=int64(len(s.reactions));result.TotalReports=int64(len(s.reports));result.MaxTip=s.maxTip;score=s.tip+result.TotalReactions}
 for _,other:=range data.allStreams{var value int64;if v:=activity.streams[other];v!=nil{value=v.tip+int64(len(v.reactions))};if value>score || value==score && other>id{result.Rank++}}
 data.RUnlock();activity.RUnlock();return c.JSON(200,result)
}
func userStats(c echo.Context)error{
 if err:=verifyUserSession(c);err!=nil{return err}
 name:=c.Param("username");activity.RLock();data.RLock()
 uid,ok:=data.names[name];if !ok{data.RUnlock();activity.RUnlock();return echo.NewHTTPError(400,"user not found")}
 result:=UserStatistics{Rank:1};emoji:=make(map[string]int64)
 for _,id:=range data.ownerStreams[uid]{if s:=activity.streams[id];s!=nil{result.TotalTip+=s.tip;result.ViewersCount+=s.viewersCount;result.TotalReactions+=int64(len(s.reactions));result.TotalLivecomments+=int64(len(s.comments));for k,v:=range s.emoji{emoji[k]+=v}}}
 var max int64;for k,v:=range emoji{if v>max || (v==max && k>result.FavoriteEmoji){max=v;result.FavoriteEmoji=k}}
 scores:=make(map[int64]int64)
 for id,s:=range activity.streams{scores[data.streams[id].Owner.ID]+=s.tip+int64(len(s.reactions))}
 score:=result.TotalTip+result.TotalReactions
 for id,u:=range data.users{v:=scores[id];if v>score || v==score && u.Name>name{result.Rank++}}
 data.RUnlock();activity.RUnlock();return c.JSON(200,result)
}
func payment(c echo.Context)error{activity.RLock();v:=activity.totalTip;activity.RUnlock();return c.JSON(200,PaymentResult{TotalTip:v})}
EOF
