var zoneLabels=[]byte("\x01u\x06isucon\x03dev\x00")
func wireName(name string)string{
 var b strings.Builder
 for _,label:=range strings.Split(strings.TrimSuffix(strings.ToLower(name),"."),"."){if len(label)>63||len(label)==0{return ""};b.WriteByte(byte(len(label)));b.WriteString(label)};b.WriteByte(0);return b.String()
}
// Answer ordinary, uncompressed IN/A questions without re-encoding their
// names. More complex DNS messages still go through the general parser.
func addressAnswer(q,dst []byte)([]byte,bool){
 if len(q)<17 || q[2]&0xf8!=0 || binary.BigEndian.Uint16(q[4:6])!=1{return nil,false}
 pos:=12;origin:=-1
 for{
 if pos>=len(q)||pos-12>=255{return nil,false}
 if origin<0&&len(q)-pos>=len(zoneLabels)&&bytes.Equal(q[pos:pos+len(zoneLabels)],zoneLabels){origin=pos}
 n:=int(q[pos]);pos++;if n==0{break};if n>63||n>len(q)-pos{return nil,false}
 for _,v:=range q[pos:pos+n]{if v>='A'&&v<='Z'{return nil,false}}
